function fontKey(font) {
  const paint = font.paintFamily && font.paintFamily !== font.family ? `${font.paintFamily}>` : "";
  return `${font.bold ? "bold " : ""}${font.italic ? "italic " : ""}${font.kerning ? "kern " : ""}${font.size}px ${paint}${font.family}`;
}
